import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import assert from 'node:assert/strict';
import { balancedRoundOrder } from '../../framework-comparison/src/balanced-round-order.mjs';
import { measureSsrRequest, runSustainedSsrWindow, runSsrBurst, resetSsrClientConnections } from '../../framework-comparison/src/ssr-benchmark-client.mjs';
import { startSsrWorker, stopSsrWorker } from '../../framework-comparison/src/ssr-worker-controller.mjs';
import { availableSsrRuntimes } from '../../framework-comparison/src/ssr-run-environment.mjs';
import { startComparisonServer } from '../../framework-comparison/src/server.mjs';
const root = path.resolve('.tmp/ssr-experiments');
const suite = path.resolve('framework-comparison');
const confirm = process.argv.includes('--confirm');
const latency = process.argv.includes('--latency');
const names = confirm ? ['baseline', 'both'] : ['baseline', 'utf8', 'getters', 'both'];
const output = path.join(root, latency ? 'http-latency.json' : confirm ? 'http-confirm.json' : 'http-screen.json');
const original = await readFile(path.join(suite, 'src/ssr-benchmark-worker.mjs'), 'utf8');
for (const kind of ['baseline', 'candidate']) {
 const source = original.replace(/from '\.\/([^']+)'/g, (_, file) => `from '${pathToFileURL(path.join(suite, 'src', file)).href}'`)
 .replace("resolve(import.meta.dirname, '..')", JSON.stringify(suite))
 .replace("from '@exactjs/server'", `from '${pathToFileURL(path.join(root, `response-${kind}/response-body.js`)).href}'`);
 await writeFile(path.join(root, `http-${kind}.mjs`), source);
}
const service = await startComparisonServer();
const report = { createdAt: new Date().toISOString(), epochs: [] };
let identity;
function check(samples) {
 for (const sample of samples) { assert.ok(sample.meaningful); identity ??= `${sample.bytes}:${sample.hash}`; assert.equal(`${sample.bytes}:${sample.hash}`, identity); }
}
try {
 for (let epoch = 0; epoch < 4; epoch++) {
  const entries = [];
  try {
   for (const name of balancedRoundOrder(names, epoch)) {
    const worker = await startSsrWorker({ runtime: availableSsrRuntimes('node')[0], participantId: 'exact', transport: 'node-http', workingDirectory: suite, serviceUrl: service.url,
     workerPath: path.join(root, `http-${name === 'getters' || name === 'both' ? 'candidate' : 'baseline'}.mjs`),
     environment: { COMPARISON_EXACT_SERVER_ENTRY: path.join(root, `${name === 'utf8' || name === 'both' ? 'candidate' : 'baseline'}.mjs`) } });
    entries.push({ name, worker });
   }
   for (const { worker } of entries) { check([await measureSsrRequest(worker.url)]); check((await runSustainedSsrWindow(worker.url, 32, 2000)).samples); }
   const windows = [], sequential = [], bursts = [];
   if (latency) for (let round=0;round<30;round++) for(const {name,worker} of balancedRoundOrder(entries,round,epoch)) {
    for(let i=0;i<25;i++) {const single=await measureSsrRequest(worker.url);check([single]);sequential.push({name,round,totalMs:single.totalMs});}
   }
   for (let round = 0; round < (latency ? 0 : confirm ? 30 : 20); round++) {
    for (const { name, worker } of balancedRoundOrder(entries, round, epoch)) {
     for (const lane of balancedRoundOrder(confirm ? ['service', 'preloaded'] : ['service'], round, epoch)) {
      const result = await runSustainedSsrWindow(worker.url + (lane === 'preloaded' ? '?__benchmarkPreloaded' : ''), 32, 500); check(result.samples);
      windows.push({ name, round, lane, requests: result.samples.length, elapsedMs: result.elapsedMs });
     }
     if (confirm) { const single = await measureSsrRequest(worker.url); check([single]); sequential.push({name,round,totalMs:single.totalMs}); const burst = await runSsrBurst(worker.url,32,32); check(burst.samples); bursts.push({name,round,elapsedMs:burst.elapsedMs}); }
    }
   }
   report.epochs.push({ epoch, windows, sequential, bursts });
   await writeFile(output, JSON.stringify(report, null, 2));
   if(latency)console.log('Latency population',epoch+1,Object.fromEntries(names.map(name=>{const samples=sequential.filter(s=>s.name===name);return[name,samples.reduce((n,s)=>n+s.totalMs,0)/samples.length];})));
   for (const lane of confirm ? ['service','preloaded'] : ['service']) console.log('HTTP population', epoch + 1, lane, Object.fromEntries(names.map(name => { const samples = windows.filter(s => s.name === name && s.lane === lane); return [name, 1000 * samples.reduce((n,s)=>n+s.requests,0)/samples.reduce((n,s)=>n+s.elapsedMs,0)]; })));
  } finally { for (const { worker } of entries) await stopSsrWorker(worker); resetSsrClientConnections(); }
 }
 report.complete = true; report.responseIdentity = identity;
 await writeFile(output, JSON.stringify(report, null, 2));
} finally { await service.close(); }

