import { fork } from 'node:child_process';
import { once } from 'node:events';
import { writeFile } from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import { balancedRoundOrder } from '../../framework-comparison/src/balanced-round-order.mjs';
const names = process.argv.slice(2);
if (!names.length) names.push('baseline', 'domain', 'ascii', 'combined');
const root = path.resolve('.tmp/ssr-experiments');
const epochs = [];
let identity;
async function measure(child, iterations) {
	const result = once(child, 'message');
	child.send({ iterations });
	const [sample] = await result;
	identity ??= `${sample.bytes}:${sample.hash}`;
	assert.equal(`${sample.bytes}:${sample.hash}`, identity);
	return sample;
}
for (let epoch = 0; epoch < 4; epoch++) {
	const workers = [];
	try {
		for (const name of balancedRoundOrder(names, epoch)) {
			const child = fork(path.join(root, 'render-worker.mjs'), [path.join(root, `${name}.mjs`)], { windowsHide: true, stdio: ['ignore', 'inherit', 'inherit', 'ipc'] });
			workers.push({ name, child });
			await once(child, 'message');
		}
		for (const entry of workers) await measure(entry.child, 15000);
		const samples = [];
		for (let round = 0; round < 20; round++) for (const entry of balancedRoundOrder(workers, round, epoch))
			 samples.push({ round, name: entry.name, ...await measure(entry.child, 2000) });
		epochs.push({ epoch, samples });
		await writeFile(path.join(root, 'render-screen.json'), JSON.stringify({ epochs }, null, 2));
		console.log('render screen population', epoch + 1, Object.fromEntries(names.map((name) => [name, samples.filter(s => s.name === name).reduce((sum, s) => sum + s.elapsedMs, 0) / 40000 * 1000])));
	} finally {
		for (const { child } of workers) {
			if (child.exitCode === null) { const done = once(child, 'exit'); child.kill(); await done; }
		}
	}
}

