import { performance } from 'node:perf_hooks';
import { writeFile } from 'node:fs/promises';
import { balancedRoundOrder } from '../../framework-comparison/src/balanced-round-order.mjs';
import * as baseline from './response-baseline/response-body.js';
import * as candidate from './response-candidate/response-body.js';
const versions = [{ name: 'baseline', api: baseline }, { name: 'candidate', api: candidate }];
const headers = { 'content-type': 'text/html' };
function produce(write) { write('hello'); }
let sink;
function run(api, iterations) {
 const start = performance.now();
 for (let i=0; i<iterations; i++) { const response = api.createExactProducedResponse(200, headers, produce); sink = response.body; }
 return performance.now() - start;
}
for (const { api } of versions) run(api, 50000);
const samples = [];
for (let round=0; round<20; round++) for (const { name, api } of balancedRoundOrder(versions, round)) samples.push({ name, round, elapsedMs: run(api, 50000) });
const heap = [];
for (let round=0; round<6; round++) for (const { name, api } of balancedRoundOrder(versions, round)) {
 global.gc(); const before = process.memoryUsage().heapUsed;
 const responses = Array.from({ length: 50000 }, () => api.createExactProducedResponse(200, headers, produce));
 global.gc(); heap.push({ name, round, bytesPerResponse: (process.memoryUsage().heapUsed - before)/responses.length });
 sink = responses[responses.length-1]; responses.length=0; sink=undefined;
}
await writeFile('.tmp/ssr-experiments/response-screen.json', JSON.stringify({samples,heap},null,2));
console.log({samples,heap});

