import { readFile, writeFile } from 'node:fs/promises';
import { performance } from 'node:perf_hooks';
import assert from 'node:assert/strict';
import { balancedRoundOrder } from '../../framework-comparison/src/balanced-round-order.mjs';
const source = await readFile('packages/ssr/dist/render/utf8.js', 'utf8');
const old = source.replace(/const firstNonAscii = [\s\S]*?let bytes = firstNonAscii;/, 'const firstNonAscii = 0; let bytes = 0;');
assert.notEqual(source, old);
const baseline = await import(`data:text/javascript;base64,${Buffer.from(old).toString('base64')}`);
const candidate = await import(`data:text/javascript;base64,${Buffer.from(source).toString('base64')}`);
const inputs = { short: 'a'.repeat(24), ascii: 'a'.repeat(2048), unicodeEarly: 'é'+'a'.repeat(2047), unicodeLate: 'a'.repeat(2047)+'é', cjk: '文'.repeat(2048) };
const names = [{ name: 'baseline', fn: baseline.utf8ByteLength }, { name: 'candidate', fn: candidate.utf8ByteLength }];
let sink=0;
function run(fn, value, iterations) { const start=performance.now(); for(let i=0;i<iterations;i++) sink += fn(value); return performance.now()-start; }
const samples=[];
for(const [input,value] of Object.entries(inputs)) {
 for(const {fn} of names) { assert.equal(fn(value),Buffer.byteLength(value)); run(fn,value,20000); }
 for(let round=0;round<20;round++) for(const {name,fn} of balancedRoundOrder(names,round)) samples.push({input,name,round,elapsedMs:run(fn,value,20000)});
}
await writeFile('.tmp/ssr-experiments/utf8-screen.json',JSON.stringify({samples,sink},null,2));
for(const input of Object.keys(inputs)) console.log(input,Object.fromEntries(names.map(({name})=>[name,samples.filter(s=>s.input===input&&s.name===name).reduce((n,s)=>n+s.elapsedMs,0)/400000*1000])));
